WITH src AS (SELECT *, CEIL(cost) AS cost_whole FROM shipments WHERE shipped_date BETWEEN '2024-04-21' AND '2025-03-10' AND order_id IN (25, 27, 30, 32)), summary AS (SELECT MONTH(delivered_date) AS delivered_month, status, ROUND((100 * SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_returned FROM src GROUP BY MONTH(delivered_date), status) SELECT delivered_month, status, pct_returned FROM summary ORDER BY status, delivered_month DESC;
